-- Lesson content rewrite: c_itf_d1, c_itf_d2, c_itf_d3, c_itf_d4, c_itf_d5, c_itf_d6
-- New slide format (terms at a glance, examples, comparisons, diagrams,
-- practice questions). Title slides kept; mini-exam questions untouched.
-- Safe to re-run: the current content is backed up once first.

create table if not exists lesson_content_backup (
  lesson_id uuid not null, content_blocks jsonb not null,
  backed_up_at timestamptz not null default now(), note text);
alter table lesson_content_backup enable row level security;

insert into lesson_content_backup (lesson_id, content_blocks, note)
select id, content_blocks, 'before content rewrite (c_itf_d1, c_itf_d2, c_itf_d3, c_itf_d4, c_itf_d5, c_itf_d6)' from lessons where id in ('9f29720a-3dae-4d8c-a628-7721f757eda6', 'a6ae551c-d2bd-4a25-b2ea-495ea46c6e7d', '45d142b5-65a7-4604-ba7c-074642588c1a', '39af7424-0365-4473-9366-5a6fd4731fc5', 'f8031d71-b2fb-48c7-92aa-e8b2f4a286e3', 'c0dec567-da50-4810-8a31-745cfc36c416', '272bd130-df37-4ae8-848c-4a984163ecbf', '56588cad-45e3-412c-adab-a9a940ece395', '0561be9d-c409-4f23-b510-5eb16850d281', '33705071-4555-425b-841c-6332478845c2', 'e1d2894f-31ae-46c9-aaa3-ebbd136f6bb5', 'f1b85376-459e-4d7b-a0b7-93eb8242b32e', '5b03aae1-fcb9-441b-9f78-b81edb9dc29e', '43722f99-f0c3-4310-95e9-18b960e2f326', '523e10fc-b381-420f-9b28-e6fa92425f7a', '2f2cfb95-3c5b-442a-aa85-a024f6571284', '79c2970b-936d-470d-ae9e-c4f8a0c4bf44', 'e314f96e-b421-4801-98a5-fa7e1dac946e', '45b23295-f048-41a2-8221-0b65f3a037d6', 'a6a73d5c-0941-4459-b50d-1270a9ce7606', '91cf6e16-b6e6-4884-96a7-9602aadabe86', '22f3e524-0774-4009-b710-92e8a87cd641', '41d28d54-760d-4c3c-80b5-f032fa9c9490', '9b8ae655-fd49-42c6-aa93-419fc339c0a0', '525daf65-4b11-402d-8b33-902f749884b1', '5916bbf9-892c-49f6-8281-eb88d4f775cc', '65617e8d-648d-4f07-b97a-6a3eacd3dfd9', '65f8fc25-e5b4-418b-aef1-81c6777aaa27', '7d48ed47-4dd5-4960-af3c-5b41d03ea273', '19b5b480-fb95-41a3-9e4d-9df67c4b83dc', '3cc2f3a9-40fc-4f55-8039-6d88b55d254e', '3af1d327-5bb1-411f-906e-d0db6b93408d', 'b5808f8a-98b3-475e-8db2-12680d44cbc5', '4569d444-292a-4e07-9696-c2a45915f549', '750da6db-477d-4178-b607-427fa6da4d40', '17a5674f-f7df-44d4-9e8a-eb595ac62fda', '27dc0556-3ac3-4a4a-9eec-ea5094cdf8b5', '58c70f8e-cd14-4c0e-b4f8-3236b5902525', 'd17ffa14-75ec-4522-8a90-9861f60adc70', '9b85d226-4265-4567-8a80-01f5c190ba9f', 'f3ae18ae-5696-425f-87fa-1555f2f8ed33', '701460a1-6388-4b44-b480-2872db4d4310', 'eb746029-2bfe-4314-9abf-e39972f660d8', '3d6f9ebe-9cb9-4020-8e5e-a37a8d419579')
  and not exists (select 1 from lesson_content_backup b where b.lesson_id = lessons.id and b.note = 'before content rewrite (c_itf_d1, c_itf_d2, c_itf_d3, c_itf_d4, c_itf_d5, c_itf_d6)');

-- What the ITF+ Exam Actually Tests
update lessons set content_blocks = '[{"text": "What the ITF+ Exam Actually Tests", "type": "title", "overview": "A map of the six domains covered in this course, and how CompTIA actually scores the FC0-U61 exam.", "examContext": "Why this matters: domain weights tell you where to put your study time before you spend a single hour on content."}, {"type": "paragraph", "text": "CompTIA IT Fundamentals (ITF+) is the entry-level, no-prerequisite certification for people new to IT, or in adjacent roles like sales and support who need baseline IT literacy."}, {"type": "term_set", "heading": "The exam at a glance", "terms": [{"term": "Exam", "short": "CompTIA IT Fundamentals FC0-U61."}, {"term": "Length", "short": "75 questions in 60 minutes."}, {"term": "Question types", "short": "Multiple choice."}, {"term": "Passing score", "short": "650 on a 100 to 900 scale."}]}, {"type": "compare", "heading": "The six domains and their weight", "columns": ["Weight"], "rows": [{"label": "1. IT Concepts and Terminology", "values": ["17%"]}, {"label": "2. Infrastructure", "values": ["22%, the largest"]}, {"label": "3. Applications and Software", "values": ["18%"]}, {"label": "4. Software Development Concepts", "values": ["12%"]}, {"label": "5. Database Fundamentals", "values": ["11%"]}, {"label": "6. Security", "values": ["20%"]}]}, {"type": "callout", "variant": "tip", "text": "Infrastructure and Security together are 42%. ITF+ rewards precise vocabulary: knowing the exact term for what''s described."}]'::jsonb where id = '9f29720a-3dae-4d8c-a628-7721f757eda6';

-- How to Use Orivian
update lessons set content_blocks = '[{"text": "How to Use Orivian", "type": "title", "overview": "How a domain''s lessons, recap, and checkpoint fit together, and what it takes to mark a lesson complete.", "examContext": "Why this matters: understanding the platform''s rhythm up front means you spend your time studying, not figuring out the interface."}, {"type": "paragraph", "text": "Every domain in this course follows the same pattern. Learn it once and you know it everywhere."}, {"type": "diagram", "heading": "Inside a domain", "diagram": {"kind": "flow", "steps": [{"label": "Lessons", "note": "Each lesson ends in a 10-question mini-exam. 80% to pass; retake as often as you like."}, {"label": "Domain recap", "note": "The highest-yield facts from every lesson, plus rapid practice questions. No exam."}, {"label": "Domain checkpoint", "note": "A longer exam across the whole domain, with fresh scenarios. The real test of whether it stuck."}]}}, {"type": "term_set", "heading": "How a lesson is laid out", "terms": [{"term": "Key terms at a glance", "short": "Every term with a one-line definition, often next to a diagram."}, {"term": "Breakdown", "short": "Terms in depth, each with an \"In practice\" example."}, {"term": "Side by side", "short": "Comparison tables for the pairs the exam loves, with an exam cue row."}, {"term": "How this shows up on the exam", "short": "Practice questions: pick an answer, then see why it''s right and what the trap was. Not scored."}, {"term": "Mini-exam", "short": "The graded questions at the end. You can review every past attempt afterwards."}]}, {"type": "term_set", "heading": "Finding your way", "terms": [{"term": "The trail map", "short": "Each course page shows your path as a trail: covered ground in green, your next waypoint in gold."}, {"term": "Next waypoint", "short": "The card at the top of the course page always points to your next step."}, {"term": "Study timer", "short": "Counts only while a lesson or exam is visible in front of you. For your awareness; never graded."}, {"term": "Listen", "short": "Any slide can be read aloud. Turn on auto-play in Voice settings to hear each slide as you press Next."}, {"term": "Keyboard", "short": "Arrow keys move between slides, L listens, N opens notes."}]}, {"type": "term_set", "heading": "Your notes", "terms": [{"term": "Write a note", "short": "Open Notes in any lesson and type; it''s linked to that lesson automatically."}, {"term": "Save to notes", "short": "Select any sentence in a lesson and tap Save to notes to keep it as a quote."}, {"term": "My Notes", "short": "Everything you''ve saved, on the Notes page, grouped by course and lesson."}], "intro": "Notes are private to you and follow your account to any device."}, {"type": "callout", "variant": "tip", "text": "One or two lessons done attentively beat a skimmed marathon. Use the recap right before the checkpoint."}]'::jsonb where id = 'a6ae551c-d2bd-4a25-b2ea-495ea46c6e7d';

-- A Study Strategy That Works
update lessons set content_blocks = '[{"text": "A Study Strategy That Works", "type": "title", "overview": "A short, practical approach to pacing your study time and retaining what you read.", "examContext": "Why this matters: ITF+ is a breadth exam covering six very different subject areas in one sitting, efficient, even coverage matters more here than deep specialization in any one area."}, {"type": "paragraph", "text": "ITF+ is a breadth exam: six very different subjects in one sitting. The most common mistake is spending time on what you already know and skipping what feels unfamiliar."}, {"type": "term_set", "heading": "How to study", "terms": [{"term": "Don''t skip databases or programming", "short": "Only 11% and 12%, but nearly a quarter of the exam together."}, {"term": "Learn the exact term", "short": "Many questions are \"name this thing\": hub or switch, RAM or ROM."}, {"term": "Recap as spaced repetition", "short": "Revisit it a few days later, right before the checkpoint."}]}, {"type": "compare", "heading": "Pairs that look alike", "columns": ["Means"], "rows": [{"label": "Authentication", "values": ["Proving who you are"]}, {"label": "Authorization", "values": ["What you''re allowed to do"]}, {"label": "Data", "values": ["Raw facts"]}, {"label": "Information", "values": ["Data given meaning"]}], "intro": "When two answers both sound right, check which one fits the exact scope of the question."}, {"type": "scenario", "prompt": "A user logs in successfully but can''t open the payroll folder. Which concept is blocking them?", "choices": [{"id": "a", "text": "Authentication"}, {"id": "b", "text": "Authorization"}, {"id": "c", "text": "Encryption"}, {"id": "d", "text": "Accounting"}], "answer": "b", "why": "They proved who they are; they just aren''t permitted to open that folder.", "trap": "Authentication sounds right because it involves logging in, but login already worked."}, {"type": "callout", "variant": "tip", "text": "When two terms both sound real, pick the one that matches the exact scope of the scenario."}]'::jsonb where id = '45d142b5-65a7-4604-ba7c-074642588c1a';

-- Notational Systems and Data Representation
update lessons set content_blocks = '[{"text": "Notational Systems and Data Representation", "type": "title", "overview": "The number systems computers use internally, and how those numbers get mapped to the letters, symbols, and characters we actually see on screen.", "examContext": "Expect direct conversion-style and definition questions distinguishing binary, hex, and decimal, plus ASCII vs. Unicode."}, {"type": "compare", "heading": "Number systems", "columns": ["Base", "Digits", "Used for"], "rows": [{"label": "Binary", "values": ["2", "0 and 1", "How computers store everything"]}, {"label": "Decimal", "values": ["10", "0 to 9", "Everyday human counting"]}, {"label": "Hexadecimal", "values": ["16", "0 to 9, A to F", "Compact way to write binary"]}]}, {"type": "key_term", "term": "Hexadecimal", "definition": "One hex digit equals exactly four bits, so two hex digits make a byte.", "example": "A web color like #FF8800 is three bytes: red FF, green 88, blue 00. MAC addresses are written in hex too."}, {"type": "key_term", "term": "Bit", "definition": "A single binary digit, 0 or 1. The smallest unit of data.", "example": "The binary number 1010 uses four bits and equals 10 in decimal, or A in hex."}, {"type": "compare", "heading": "ASCII vs. Unicode", "columns": ["ASCII", "Unicode"], "rows": [{"label": "Covers", "values": ["English letters, digits, common symbols", "Virtually every writing system, plus emoji"]}, {"label": "Size", "values": ["7 or 8 bits per character", "Variable, larger"]}]}, {"type": "scenario", "prompt": "Why is hexadecimal commonly used to write MAC addresses and colors?", "choices": [{"id": "a", "text": "It''s faster for the CPU"}, {"id": "b", "text": "Each hex digit represents exactly four bits, so it''s compact"}, {"id": "c", "text": "It supports emoji"}, {"id": "d", "text": "It''s encrypted"}], "answer": "b", "why": "Two hex digits neatly represent one byte."}, {"type": "scenario", "prompt": "An app must display Japanese, Arabic and emoji correctly. Which encoding?", "choices": [{"id": "a", "text": "ASCII"}, {"id": "b", "text": "Unicode"}, {"id": "c", "text": "Binary"}, {"id": "d", "text": "Hexadecimal"}], "answer": "b", "why": "Unicode covers virtually every character."}, {"type": "callout", "variant": "tip", "text": "Binary is base 2, decimal base 10, hex base 16. One hex digit is four bits."}]'::jsonb where id = '39af7424-0365-4473-9366-5a6fd4731fc5';

-- Data Types and Characteristics
update lessons set content_blocks = '[{"text": "Data Types and Characteristics", "type": "title", "overview": "The basic categories of data that programs and databases work with, and what distinguishes each one.", "examContext": "Expect scenario questions describing a piece of data and asking you to identify its correct data type."}, {"type": "paragraph", "text": "A **data type** tells the computer how to store a value and what you can do with it. You can add two numbers, but not two names."}, {"type": "compare", "heading": "The five data types", "columns": ["Holds", "Example"], "rows": [{"label": "Char", "values": ["One character", "''A'' or ''7''"]}, {"label": "String", "values": ["Text, a sequence of characters", "\"Jordan Lee\""]}, {"label": "Integer", "values": ["Whole numbers", "42, -12"]}, {"label": "Float", "values": ["Numbers with decimals", "3.14, -0.5"]}, {"label": "Boolean", "values": ["True or false only", "isLoggedIn = true"]}]}, {"type": "key_term", "term": "Numbers stored as strings", "definition": "Phone numbers and ZIP codes are usually strings: you never do math with them and leading zeros must survive.", "example": "Stored as an integer, the ZIP code 02134 would become 2134."}, {"type": "scenario", "prompt": "Which data type fits a product price like 19.99?", "choices": [{"id": "a", "text": "Integer"}, {"id": "b", "text": "Float"}, {"id": "c", "text": "Boolean"}, {"id": "d", "text": "Char"}], "answer": "b", "why": "It has a decimal part."}, {"type": "scenario", "prompt": "A form stores a customer''s ZIP code, 07030. Which data type is best?", "choices": [{"id": "a", "text": "Integer"}, {"id": "b", "text": "String"}, {"id": "c", "text": "Float"}, {"id": "d", "text": "Boolean"}], "answer": "b", "why": "Strings keep leading zeros and aren''t used for math.", "trap": "It looks like a number, but storing it as an integer drops the leading zero."}, {"type": "callout", "variant": "tip", "text": "Phone numbers and ZIP codes are strings. Decimals mean float; yes or no means Boolean."}]'::jsonb where id = 'f8031d71-b2fb-48c7-92aa-e8b2f4a286e3';

-- The Basics of Computing and Processing
update lessons set content_blocks = '[{"text": "The Basics of Computing and Processing", "type": "title", "overview": "The four-stage cycle, input, processing, output, and storage, that describes how any computer, from a smartphone to a server, actually works.", "examContext": "Expect scenario questions describing a specific action (typing, saving a file, printing) and asking which stage of the cycle it represents."}, {"type": "diagram", "heading": "The computing cycle", "diagram": {"kind": "cycle", "steps": [{"label": "Input", "note": "Keyboard, mouse, sensor, scanner."}, {"label": "Processing", "note": "The CPU works on the data."}, {"label": "Output", "note": "Screen, printer, speakers."}, {"label": "Storage", "note": "RAM for now; SSD or HDD for later."}]}}, {"type": "compare", "heading": "Input vs. output devices", "columns": ["Input", "Output"], "rows": [{"label": "Examples", "values": ["Keyboard, mouse, scanner, microphone", "Monitor, printer, speakers"]}, {"label": "Both", "values": ["Touchscreen, network card", "Touchscreen, network card"]}]}, {"type": "scenario", "prompt": "A user saves a document to the SSD. Which stage of the cycle is this?", "choices": [{"id": "a", "text": "Input"}, {"id": "b", "text": "Processing"}, {"id": "c", "text": "Output"}, {"id": "d", "text": "Storage"}], "answer": "d", "why": "Saving for later use is storage."}, {"type": "scenario", "prompt": "Which device is both input and output?", "choices": [{"id": "a", "text": "Keyboard"}, {"id": "b", "text": "Printer"}, {"id": "c", "text": "Touchscreen"}, {"id": "d", "text": "Speaker"}], "answer": "c", "why": "It takes taps and displays images."}, {"type": "callout", "variant": "tip", "text": "Input, processing, output, storage. Some devices, like touchscreens, do both input and output."}]'::jsonb where id = 'c0dec567-da50-4810-8a31-745cfc36c416';

-- The Value of Data and Information
update lessons set content_blocks = '[{"text": "The Value of Data and Information", "type": "title", "overview": "Why data and information are treated as valuable business assets, the legal protections around intellectual property, and how organizations turn raw data into decisions.", "examContext": "Expect definition questions distinguishing data from information, and matching a scenario to trademark, copyright, or patent protection."}, {"type": "compare", "heading": "Data vs. information", "columns": ["Data", "Information"], "rows": [{"label": "What it is", "values": ["Raw facts with no context", "Data organized to be meaningful"]}, {"label": "Example", "values": ["A list of purchase timestamps", "\"Sales peak every Friday afternoon\""]}]}, {"type": "compare", "heading": "Intellectual property", "columns": ["Protects", "Example"], "rows": [{"label": "Trademark", "values": ["Brand identifiers", "A logo, product name or slogan"]}, {"label": "Copyright", "values": ["Original creative works", "Software code, books, music"]}, {"label": "Patent", "values": ["New inventions or processes", "A new battery design"]}]}, {"type": "diagram", "heading": "Data-driven decisions", "diagram": {"kind": "flow", "steps": [{"label": "Capture", "note": "Collect the data."}, {"label": "Correlate", "note": "Find patterns with other data."}, {"label": "Report", "note": "Present it so people can act."}]}}, {"type": "scenario", "prompt": "A startup wants to stop competitors from using its logo. Which protection?", "choices": [{"id": "a", "text": "Copyright"}, {"id": "b", "text": "Trademark"}, {"id": "c", "text": "Patent"}, {"id": "d", "text": "License"}], "answer": "b", "why": "Logos are brand identifiers."}, {"type": "scenario", "prompt": "A developer''s source code is protected by what?", "choices": [{"id": "a", "text": "Trademark"}, {"id": "b", "text": "Patent"}, {"id": "c", "text": "Copyright"}, {"id": "d", "text": "NDA"}], "answer": "c", "why": "Code is a creative work."}, {"type": "callout", "variant": "tip", "text": "Logo: trademark. Code: copyright. New invention: patent."}]'::jsonb where id = '272bd130-df37-4ae8-848c-4a984163ecbf';

-- Units of Measure
update lessons set content_blocks = '[{"text": "Units of Measure", "type": "title", "overview": "The units used to measure storage capacity, network throughput, and processor speed, and how they relate to each other.", "examContext": "Expect direct recall questions on unit ordering (which is bigger, a GB or a TB?) and on which unit measures which kind of quantity."}, {"type": "diagram", "heading": "Storage units", "diagram": {"kind": "ladder", "rungs": [{"label": "Petabyte (PB)", "note": "About 1,000 TB."}, {"label": "Terabyte (TB)", "note": "About 1,000 GB."}, {"label": "Gigabyte (GB)", "note": "About 1,000 MB."}, {"label": "Megabyte (MB)", "note": "About 1,000 KB."}, {"label": "Kilobyte (KB)", "note": "About 1,000 bytes."}, {"label": "Byte", "note": "8 bits; one character."}, {"label": "Bit", "note": "A single 0 or 1."}], "top": "largest", "bottom": "smallest"}}, {"type": "compare", "heading": "Three families of units", "columns": ["Unit", "Examples"], "rows": [{"label": "Storage", "values": ["Bytes", "KB, MB, GB, TB"]}, {"label": "Network throughput", "values": ["Bits per second", "Kbps, Mbps, Gbps"]}, {"label": "CPU speed", "values": ["Hertz", "MHz, GHz"]}]}, {"type": "key_term", "term": "Bits vs. bytes", "definition": "Network speeds use bits; file sizes use bytes. Divide by 8 to convert.", "example": "A 100 Mbps connection moves about 12.5 MB per second."}, {"type": "scenario", "prompt": "An ISP advertises \"500 Mbps.\" What does this measure?", "choices": [{"id": "a", "text": "Storage capacity"}, {"id": "b", "text": "Network throughput in bits per second"}, {"id": "c", "text": "CPU speed"}, {"id": "d", "text": "RAM size"}], "answer": "b", "why": "Lowercase b with ps is bits per second."}, {"type": "scenario", "prompt": "Which is largest?", "choices": [{"id": "a", "text": "2,000 MB"}, {"id": "b", "text": "1 TB"}, {"id": "c", "text": "500 GB"}, {"id": "d", "text": "900 KB"}], "answer": "b", "why": "1 TB is about 1,000 GB."}, {"type": "callout", "variant": "tip", "text": "Storage in bytes, network in bits, CPU in hertz. Divide bits by 8 for bytes."}]'::jsonb where id = '56588cad-45e3-412c-adab-a9a940ece395';

-- Troubleshooting Methodology
update lessons set content_blocks = '[{"text": "Troubleshooting Methodology", "type": "title", "overview": "A structured, repeatable process for diagnosing and resolving IT problems, rather than guessing at fixes.", "examContext": "Expect ordering questions and scenario questions describing a step being skipped, asking you to identify which one."}, {"type": "diagram", "heading": "The troubleshooting steps", "diagram": {"kind": "flow", "steps": [{"label": "Identify the problem", "note": "Question users, find what changed, duplicate it."}, {"label": "Research", "note": "Knowledge base or internet."}, {"label": "Establish a theory", "note": "Question the obvious first."}, {"label": "Test the theory"}, {"label": "Plan of action", "note": "And its possible effects."}, {"label": "Implement or escalate"}, {"label": "Verify", "note": "And add preventive measures."}, {"label": "Document"}]}}, {"type": "key_term", "term": "Divide and conquer", "definition": "Test sections of a system separately to narrow down which part is at fault.", "example": "A PC can''t reach the web: ping the router (works), then a website by IP (fails). The problem is between the router and the internet."}, {"type": "key_term", "term": "Approach problems individually", "definition": "Several unrelated symptoms get troubleshot one at a time, not assumed to share a cause.", "example": "A user''s printer jams and their email won''t sync. Those are two tickets, not one mystery."}, {"type": "scenario", "prompt": "A technician finds a fix and applies it. What comes next?", "choices": [{"id": "a", "text": "Document"}, {"id": "b", "text": "Verify full functionality"}, {"id": "c", "text": "Establish a theory"}, {"id": "d", "text": "Research"}], "answer": "b", "why": "Verify before documenting."}, {"type": "scenario", "prompt": "A technician replaces a monitor immediately when a user says the screen is blank. What was skipped?", "choices": [{"id": "a", "text": "Documentation"}, {"id": "b", "text": "Identifying the problem and testing a theory"}, {"id": "c", "text": "Verification"}, {"id": "d", "text": "Escalation"}], "answer": "b", "why": "A loose cable or power switch would have been checked first."}, {"type": "callout", "variant": "tip", "text": "Identify first, document last. Several symptoms? Handle them one at a time."}]'::jsonb where id = '0561be9d-c409-4f23-b510-5eb16850d281';

-- Domain 1 Recap
update lessons set content_blocks = '[{"text": "Domain 1 Recap: IT Concepts and Terminology", "type": "title", "overview": "A condensed pass over every lesson in this domain, notational systems, data types, the computing cycle, the value of data/information, units of measure, and troubleshooting methodology.", "examContext": "This recap has no questions of its own; the Domain Checkpoint right after it draws fresh scenario questions from everything covered across all 6 lessons."}, {"type": "term_set", "heading": "Numbers and data", "terms": [{"term": "Binary / decimal / hex", "short": "Base 2 / 10 / 16; one hex digit is four bits."}, {"term": "ASCII / Unicode", "short": "English-centric / every language."}, {"term": "Char, string, integer, float, Boolean", "short": "Character, text, whole, decimal, true or false."}]}, {"type": "term_set", "heading": "Computing and value", "terms": [{"term": "Cycle", "short": "Input, processing, output, storage."}, {"term": "Data / information", "short": "Raw facts / facts with meaning."}, {"term": "Trademark, copyright, patent", "short": "Brand, creative work, invention."}]}, {"type": "term_set", "heading": "Units and troubleshooting", "terms": [{"term": "Bytes / bits / hertz", "short": "Storage / network / CPU."}, {"term": "Steps", "short": "Identify, research, theory, test, plan, implement, verify, document."}, {"term": "Divide and conquer", "short": "Test sections separately."}]}, {"type": "scenario", "prompt": "Which data type stores true or false?", "choices": [{"id": "a", "text": "String"}, {"id": "b", "text": "Boolean"}, {"id": "c", "text": "Float"}, {"id": "d", "text": "Char"}], "answer": "b", "why": "Boolean."}, {"type": "scenario", "prompt": "CPU speed is measured in what?", "choices": [{"id": "a", "text": "Mbps"}, {"id": "b", "text": "GB"}, {"id": "c", "text": "GHz"}, {"id": "d", "text": "PB"}], "answer": "c", "why": "Hertz."}, {"type": "scenario", "prompt": "A company''s slogan is protected by what?", "choices": [{"id": "a", "text": "Copyright"}, {"id": "b", "text": "Trademark"}, {"id": "c", "text": "Patent"}, {"id": "d", "text": "Encryption"}], "answer": "b", "why": "A brand identifier."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '33705071-4555-425b-841c-6332478845c2';

-- I/O Device Interfaces
update lessons set content_blocks = '[{"text": "I/O Device Interfaces", "type": "title", "overview": "The common wired and wireless connectors used to attach peripherals, networking gear, and displays to a computer.", "examContext": "Expect ''match the connector to its use'' questions, especially telling RJ-11 from RJ-45, and picking the right video connector."}, {"type": "compare", "heading": "RJ-11 vs. RJ-45", "columns": ["RJ-11", "RJ-45"], "rows": [{"label": "Pins", "values": ["4 or 6", "8"]}, {"label": "Size", "values": ["Smaller", "Larger"]}, {"label": "Used for", "values": ["Phone lines, older DSL", "Ethernet"]}]}, {"type": "term_set", "heading": "Short-range wireless", "terms": [{"term": "Bluetooth", "short": "Pairs keyboards, mice, headsets."}, {"term": "NFC", "short": "A few centimeters; contactless payments."}, {"term": "RF", "short": "Wireless mice and keyboards with a USB dongle."}]}, {"type": "compare", "heading": "Data and video connectors", "columns": ["Signal", "Notes"], "rows": [{"label": "USB", "values": ["Data and power", "Most common; USB-C is reversible"]}, {"label": "Thunderbolt", "values": ["Data, video, power", "Often uses the USB-C shape"]}, {"label": "FireWire", "values": ["Data", "Legacy"]}, {"label": "VGA", "values": ["Analog video", "Blue, 15 pins; legacy"]}, {"label": "DVI", "values": ["Digital video", "Step up from VGA"]}, {"label": "HDMI", "values": ["Digital video and audio", "Most common for TVs and monitors"]}, {"label": "DisplayPort", "values": ["Digital video and audio", "Common on PC monitors"]}]}, {"type": "scenario", "prompt": "A technician needs to plug a PC into a wall network jack. Which connector?", "choices": [{"id": "a", "text": "RJ-11"}, {"id": "b", "text": "RJ-45"}, {"id": "c", "text": "VGA"}, {"id": "d", "text": "HDMI"}], "answer": "b", "why": "Ethernet uses RJ-45."}, {"type": "scenario", "prompt": "Which video connector is analog only?", "choices": [{"id": "a", "text": "HDMI"}, {"id": "b", "text": "DisplayPort"}, {"id": "c", "text": "VGA"}, {"id": "d", "text": "DVI"}], "answer": "c", "why": "VGA is analog."}, {"type": "callout", "variant": "tip", "text": "RJ-11 is phone, RJ-45 is Ethernet. VGA is the analog one."}]'::jsonb where id = 'e1d2894f-31ae-46c9-aaa3-ebbd136f6bb5';

-- Installing Peripheral Devices
update lessons set content_blocks = '[{"text": "Installing Peripheral Devices", "type": "title", "overview": "How an operating system recognizes and configures a newly connected peripheral, and how network-attached devices get configured differently from directly-connected ones.", "examContext": "Expect scenario questions asking what to do when a device isn''t recognized, or how a network printer gets configured versus a USB one."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Plug and play", "short": "The OS detects and configures a device automatically."}, {"term": "Driver", "short": "Software that lets the OS talk to specific hardware."}, {"term": "IP-based device", "short": "Has its own network address; anyone authorized on the network can use it."}, {"term": "Web-based configuration", "short": "Manage a device by browsing to its IP address."}]}, {"type": "compare", "heading": "Directly attached vs. networked", "columns": ["Directly attached", "IP-based"], "rows": [{"label": "Connects via", "values": ["USB or Bluetooth to one PC", "The network"]}, {"label": "Setup", "values": ["Plug and play and drivers", "IP address and web configuration"]}, {"label": "Shared?", "values": ["Only through that PC", "By everyone authorized"]}]}, {"type": "key_term", "term": "Driver", "definition": "Without the right one, a device may not work at all, or only partly.", "example": "A drawing tablet moves the cursor, but pressure sensitivity only works after the maker''s driver is installed."}, {"type": "scenario", "prompt": "A plug-and-play USB device isn''t recognized. What should be tried first?", "choices": [{"id": "a", "text": "Replace the PC"}, {"id": "b", "text": "A different cable or port, then check for an updated driver"}, {"id": "c", "text": "Reinstall the OS"}, {"id": "d", "text": "Change the IP address"}], "answer": "b", "why": "Start simple: cable, port, driver."}, {"type": "scenario", "prompt": "How would an admin change settings on a network printer?", "choices": [{"id": "a", "text": "Only from the printer''s USB port"}, {"id": "b", "text": "Browse to the printer''s IP address for its web configuration page"}, {"id": "c", "text": "Through Bluetooth"}, {"id": "d", "text": "By reinstalling the OS"}], "answer": "b", "why": "Networked devices often have built-in web configuration."}, {"type": "callout", "variant": "tip", "text": "Device not recognized: cable, port, then driver. Network devices are configured through their IP."}]'::jsonb where id = 'f1b85376-459e-4d7b-a0b7-93eb8242b32e';

-- Internal Computing Components
update lessons set content_blocks = '[{"text": "Internal Computing Components", "type": "title", "overview": "The major hardware components inside a desktop or laptop case, and the role each one plays.", "examContext": "Expect definition-matching questions: given a description of a function, identify which internal component performs it."}, {"type": "compare", "heading": "What each component does", "columns": ["Role"], "rows": [{"label": "Motherboard", "values": ["Connects every component"]}, {"label": "BIOS / UEFI", "values": ["Firmware that starts the hardware and boot"]}, {"label": "CPU", "values": ["Executes instructions; multiple cores work in parallel"]}, {"label": "RAM", "values": ["Fast, temporary memory for active work"]}, {"label": "Storage", "values": ["Keeps data permanently"]}, {"label": "GPU", "values": ["Renders graphics; integrated or a separate card"]}, {"label": "Cooling", "values": ["Fans or liquid keep parts from overheating"]}, {"label": "NIC", "values": ["Connects to a network, wired or wireless"]}]}, {"type": "compare", "heading": "Volatile vs. non-volatile", "columns": ["RAM", "Storage (SSD, HDD)"], "rows": [{"label": "Without power", "values": ["Contents lost", "Contents kept"]}, {"label": "Speed", "values": ["Very fast", "Slower"]}, {"label": "Purpose", "values": ["Active work", "Long-term data"]}]}, {"type": "scenario", "prompt": "A user''s unsaved document vanishes when the power goes out. Where was it?", "choices": [{"id": "a", "text": "SSD"}, {"id": "b", "text": "RAM"}, {"id": "c", "text": "BIOS"}, {"id": "d", "text": "NIC"}], "answer": "b", "why": "RAM is volatile."}, {"type": "scenario", "prompt": "Which component starts the boot process before the operating system loads?", "choices": [{"id": "a", "text": "CPU"}, {"id": "b", "text": "BIOS / UEFI"}, {"id": "c", "text": "GPU"}, {"id": "d", "text": "RAM"}], "answer": "b", "why": "Firmware initializes the hardware."}, {"type": "callout", "variant": "tip", "text": "RAM forgets without power; storage remembers. BIOS or UEFI starts everything."}]'::jsonb where id = '5b03aae1-fcb9-441b-9f78-b81edb9dc29e';

-- Internet Service Types
update lessons set content_blocks = '[{"text": "Internet Service Types", "type": "title", "overview": "The major ways homes and businesses connect to the internet, both wired and wireless.", "examContext": "Expect questions asking you to identify a service type from a description, or to compare relative speed and availability."}, {"type": "compare", "heading": "Internet service types", "columns": ["Strength", "Tradeoff"], "rows": [{"label": "Fiber", "values": ["Fastest, most reliable", "Limited availability"]}, {"label": "Cable", "values": ["Widely available, good speed", "Shared bandwidth slows at peak times"]}, {"label": "DSL", "values": ["Uses phone lines", "Slower; drops with distance"]}, {"label": "Fixed wireless (RF)", "values": ["Reaches rural sites from a tower", "Needs line of sight"]}, {"label": "Satellite", "values": ["Available almost anywhere", "Highest latency"]}, {"label": "Cellular", "values": ["Mobile and convenient", "Data caps, variable speed"]}]}, {"type": "key_term", "term": "Latency", "definition": "The delay before data arrives. Satellite''s long trip to orbit and back makes it the highest.", "example": "Downloads on satellite are fine, but video calls lag and online games stutter."}, {"type": "scenario", "prompt": "A gamer in a remote area chooses satellite internet. What problem should they expect?", "choices": [{"id": "a", "text": "Low download speeds"}, {"id": "b", "text": "High latency"}, {"id": "c", "text": "No availability"}, {"id": "d", "text": "Data cannot be encrypted"}], "answer": "b", "why": "The orbital round trip adds delay."}, {"type": "scenario", "prompt": "A neighborhood''s internet slows every evening when everyone is online. Which service is most likely?", "choices": [{"id": "a", "text": "Fiber"}, {"id": "b", "text": "Cable"}, {"id": "c", "text": "Satellite"}, {"id": "d", "text": "DSL"}], "answer": "b", "why": "Cable bandwidth is shared locally."}, {"type": "callout", "variant": "tip", "text": "Fiber is fastest; satellite has the most latency; cable is shared."}]'::jsonb where id = '43722f99-f0c3-4310-95e9-18b960e2f326';

-- Storage Types
update lessons set content_blocks = '[{"text": "Storage Types", "type": "title", "overview": "How data storage differs by permanence (volatile vs. non-volatile) and by location (local, network, or cloud).", "examContext": "Expect direct definition questions on volatile vs. non-volatile, and scenario questions about picking the right storage location."}, {"type": "compare", "heading": "Volatile vs. non-volatile", "columns": ["Volatile", "Non-volatile"], "rows": [{"label": "Example", "values": ["RAM", "SSD, HDD, USB flash drive"]}, {"label": "Keeps data without power?", "values": ["No", "Yes"]}]}, {"type": "compare", "heading": "Where storage lives", "columns": ["Local", "Network", "Cloud"], "rows": [{"label": "Location", "values": ["On the device", "A shared server or NAS on the LAN", "A provider''s servers"]}, {"label": "Access", "values": ["That device only", "Office devices", "Anywhere with internet"]}, {"label": "Weakness", "values": ["Lost with the device", "Only on the local network", "Needs internet"]}], "cue": ["\"On my laptop\"", "\"Shared office drive\"", "\"From anywhere\""]}, {"type": "scenario", "prompt": "A team wants to open the same files from home, the office and their phones. Which storage?", "choices": [{"id": "a", "text": "Local"}, {"id": "b", "text": "Network"}, {"id": "c", "text": "Cloud"}, {"id": "d", "text": "RAM"}], "answer": "c", "why": "Anywhere access points to cloud."}, {"type": "scenario", "prompt": "A small office wants one shared drive that only its computers use. Which storage?", "choices": [{"id": "a", "text": "Cloud"}, {"id": "b", "text": "Network storage (NAS)"}, {"id": "c", "text": "Local"}, {"id": "d", "text": "Volatile"}], "answer": "b", "why": "A NAS on the local network."}, {"type": "callout", "variant": "tip", "text": "\"From anywhere\" means cloud. \"Shared office drive\" means network storage."}]'::jsonb where id = '523e10fc-b381-420f-9b28-e6fa92425f7a';

-- Computing Devices and IoT
update lessons set content_blocks = '[{"text": "Computing Devices and IoT", "type": "title", "overview": "The range of devices that count as ''computing devices'' today, and what makes IoT devices distinct.", "examContext": "Expect questions asking you to classify a described device, and to identify characteristics or risks specific to IoT."}, {"type": "term_set", "heading": "Computing device types", "terms": [{"term": "Desktop and laptop", "short": "General-purpose personal computers."}, {"term": "Mobile", "short": "Smartphones and tablets."}, {"term": "Server", "short": "Provides services to other computers."}, {"term": "Embedded system", "short": "Built into another device for one job."}]}, {"type": "compare", "heading": "Embedded system vs. IoT", "columns": ["Embedded system", "IoT device"], "rows": [{"label": "Purpose", "values": ["One dedicated function", "Collect and share data over the internet"]}, {"label": "Connected?", "values": ["Not necessarily", "Always"]}, {"label": "Example", "values": ["A car''s engine control unit", "A smart doorbell, fitness tracker"]}]}, {"type": "key_term", "term": "IoT security risk", "definition": "Many IoT devices ship with default passwords and rarely updated firmware.", "example": "A smart camera still using \"admin/admin\" is taken over and used in a botnet."}, {"type": "scenario", "prompt": "A refrigerator sends inventory data to the owner''s phone over the internet. What is it?", "choices": [{"id": "a", "text": "Server"}, {"id": "b", "text": "IoT device"}, {"id": "c", "text": "Workstation"}, {"id": "d", "text": "Embedded system only"}], "answer": "b", "why": "Everyday device plus sensors plus connectivity."}, {"type": "scenario", "prompt": "Why are IoT devices often a security concern?", "choices": [{"id": "a", "text": "They''re too fast"}, {"id": "b", "text": "Weak defaults and rare firmware updates"}, {"id": "c", "text": "They use RJ-11"}, {"id": "d", "text": "They can''t connect to Wi-Fi"}], "answer": "b", "why": "Default credentials and stale firmware."}, {"type": "callout", "variant": "tip", "text": "One dedicated job: embedded. Everyday device sharing data online: IoT."}]'::jsonb where id = '2f2cfb95-3c5b-442a-aa85-a024f6571284';

-- Basic Networking Concepts
update lessons set content_blocks = '[{"text": "Basic Networking Concepts", "type": "title", "overview": "The building blocks of how data moves across a network: addressing, name resolution, network scope, common protocols, and the hardware that makes it all work.", "examContext": "This is one of the densest lessons in the domain, expect several questions on matching a device or protocol to its function."}, {"type": "compare", "heading": "IP address vs. MAC address", "columns": ["IP address", "MAC address"], "rows": [{"label": "Type", "values": ["Logical", "Physical"]}, {"label": "Assigned by", "values": ["The network", "The manufacturer"]}, {"label": "Changes?", "values": ["Can change between networks", "Permanent to the hardware"]}]}, {"type": "key_term", "term": "DNS", "definition": "Translates names like example.com into IP addresses.", "example": "Typing a website''s name works because DNS quietly looks up its numeric address."}, {"type": "term_set", "heading": "Network scope and protocols", "terms": [{"term": "LAN", "short": "A home or one office."}, {"term": "WAN", "short": "Many LANs over a large area; the internet is the largest."}, {"term": "HTTP / HTTPS", "short": "Web pages / encrypted web pages."}, {"term": "SMTP", "short": "Sends email."}, {"term": "POP3 / IMAP", "short": "Download and remove / keep synced on the server."}]}, {"type": "compare", "heading": "Core networking devices", "columns": ["Does"], "rows": [{"label": "Modem", "values": ["Connects to the ISP''s line"]}, {"label": "Router", "values": ["Moves traffic between networks using IP addresses"]}, {"label": "Switch", "values": ["Connects devices within a LAN using MAC addresses"]}, {"label": "Access point", "values": ["Adds wireless to a wired network"]}, {"label": "Firewall", "values": ["Filters traffic by rules"]}]}, {"type": "scenario", "prompt": "Which device connects a home network to the internet and directs traffic between them?", "choices": [{"id": "a", "text": "Switch"}, {"id": "b", "text": "Router"}, {"id": "c", "text": "Access point"}, {"id": "d", "text": "NIC"}], "answer": "b", "why": "Routers move traffic between networks."}, {"type": "scenario", "prompt": "Which address is burned into a network card by the manufacturer?", "choices": [{"id": "a", "text": "IP address"}, {"id": "b", "text": "MAC address"}, {"id": "c", "text": "DNS name"}, {"id": "d", "text": "SSID"}], "answer": "b", "why": "MAC addresses are physical."}, {"type": "callout", "variant": "tip", "text": "Switch: within a LAN, by MAC. Router: between networks, by IP."}]'::jsonb where id = '79c2970b-936d-470d-ae9e-c4f8a0c4bf44';

-- Installing and Securing a Basic Wireless Network
update lessons set content_blocks = '[{"text": "Installing and Securing a Basic Wireless Network", "type": "title", "overview": "The 802.11 wireless standards and the essential steps to set up and secure a home or small-office wireless network.", "examContext": "Expect a question ranking wireless encryption standards from weakest to strongest, and questions on basic SSID/password setup."}, {"type": "compare", "heading": "802.11 standards", "columns": ["Notes"], "rows": [{"label": "802.11a / b / g", "values": ["Older and slower"]}, {"label": "802.11n", "values": ["Faster, better range with multiple antennas"]}, {"label": "802.11ac", "values": ["Faster still, wider channels"]}]}, {"type": "key_term", "term": "SSID", "definition": "The wireless network''s broadcast name.", "example": "Phones list \"Lee-Home-5G\" as an available network because the router broadcasts that SSID."}, {"type": "diagram", "heading": "Wireless encryption", "diagram": {"kind": "ladder", "rungs": [{"label": "WPA2", "note": "AES; the recommended baseline (or newer where offered)."}, {"label": "WPA", "note": "Better than WEP but has weaknesses."}, {"label": "WEP", "note": "Broken; never use.", "muted": true}], "top": "strongest", "bottom": "weakest"}}, {"type": "term_set", "heading": "Setting up securely", "terms": [{"term": "Change default router credentials", "short": "First."}, {"term": "Strong Wi-Fi password", "short": "Long and unique."}, {"term": "Strongest encryption available", "short": "WPA2 or newer."}]}, {"type": "scenario", "prompt": "Which wireless encryption should never be used?", "choices": [{"id": "a", "text": "WPA2"}, {"id": "b", "text": "WPA"}, {"id": "c", "text": "WEP"}, {"id": "d", "text": "AES"}], "answer": "c", "why": "WEP is badly broken."}, {"type": "scenario", "prompt": "What''s the first step when setting up a new home router?", "choices": [{"id": "a", "text": "Rename the SSID"}, {"id": "b", "text": "Change the default admin credentials"}, {"id": "c", "text": "Enable WEP"}, {"id": "d", "text": "Hide the router"}], "answer": "b", "why": "Defaults are publicly known."}, {"type": "callout", "variant": "tip", "text": "WEP is weakest, then WPA, then WPA2. Change router defaults first."}]'::jsonb where id = 'e314f96e-b421-4801-98a5-fa7e1dac946e';

-- Domain 2 Recap
update lessons set content_blocks = '[{"text": "Domain 2 Recap", "type": "title", "overview": "The highest-yield facts from all eight Infrastructure lessons, condensed for a quick pre-checkpoint review.", "examContext": "Read this closely before attempting the Domain 2 checkpoint, Infrastructure is the single largest domain on the exam at 22%."}, {"type": "term_set", "heading": "Interfaces and components", "terms": [{"term": "RJ-11 / RJ-45", "short": "Phone / Ethernet."}, {"term": "VGA", "short": "Analog; DVI, HDMI and DisplayPort are digital."}, {"term": "Plug and play / driver", "short": "Automatic setup / OS-to-hardware software."}, {"term": "RAM / storage", "short": "Volatile / non-volatile."}, {"term": "BIOS / UEFI", "short": "Starts the boot."}]}, {"type": "term_set", "heading": "Internet and storage", "terms": [{"term": "Fiber / cable / DSL", "short": "Fastest / shared / phone lines."}, {"term": "Satellite", "short": "Highest latency."}, {"term": "Local / network / cloud", "short": "Device / shared LAN / anywhere."}, {"term": "Embedded / IoT", "short": "One job / connected everyday device."}]}, {"type": "term_set", "heading": "Networking", "terms": [{"term": "IP / MAC", "short": "Logical, changes / physical, permanent."}, {"term": "DNS", "short": "Names to IP addresses."}, {"term": "Switch / router", "short": "MAC within a LAN / IP between networks."}, {"term": "SMTP / POP3, IMAP", "short": "Send / retrieve."}, {"term": "WEP, WPA, WPA2", "short": "Weakest to strongest."}]}, {"type": "scenario", "prompt": "Which connector is used for phone lines?", "choices": [{"id": "a", "text": "RJ-45"}, {"id": "b", "text": "RJ-11"}, {"id": "c", "text": "USB"}, {"id": "d", "text": "HDMI"}], "answer": "b", "why": "RJ-11."}, {"type": "scenario", "prompt": "Which internet type has the highest latency?", "choices": [{"id": "a", "text": "Fiber"}, {"id": "b", "text": "Cable"}, {"id": "c", "text": "Satellite"}, {"id": "d", "text": "DSL"}], "answer": "c", "why": "Satellite."}, {"type": "scenario", "prompt": "What translates a website name into an IP address?", "choices": [{"id": "a", "text": "DHCP"}, {"id": "b", "text": "DNS"}, {"id": "c", "text": "MAC"}, {"id": "d", "text": "SSID"}], "answer": "b", "why": "DNS."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '45b23295-f048-41a2-8221-0b65f3a037d6';

-- The Purpose of Operating Systems
update lessons set content_blocks = '[{"text": "The Purpose of Operating Systems", "type": "title", "overview": "The core role an operating system plays as the intermediary between hardware and applications, and the main categories of OS in use today.", "examContext": "Expect questions matching a described device or use case to the correct OS category."}, {"type": "paragraph", "text": "An **operating system** manages hardware and gives applications a place to run. It allocates memory, schedules CPU time, manages files and provides the interface you use."}, {"type": "compare", "heading": "OS categories", "columns": ["Examples", "Built for"], "rows": [{"label": "Mobile", "values": ["iOS, Android", "Touchscreens, battery life, app stores"]}, {"label": "Workstation", "values": ["Windows, macOS, desktop Linux", "One user running many apps"]}, {"label": "Server", "values": ["Windows Server, server Linux", "Many users and clients; often no GUI"]}, {"label": "Embedded", "values": ["Smart TV, car infotainment", "One device, one purpose"]}]}, {"type": "scenario", "prompt": "A machine with no monitor or keyboard hosts files for 200 office computers. Which OS category?", "choices": [{"id": "a", "text": "Workstation"}, {"id": "b", "text": "Server"}, {"id": "c", "text": "Mobile"}, {"id": "d", "text": "Embedded"}], "answer": "b", "why": "It serves many clients."}, {"type": "scenario", "prompt": "A car''s dashboard system runs only navigation and media software. Which OS category?", "choices": [{"id": "a", "text": "Server"}, {"id": "b", "text": "Embedded"}, {"id": "c", "text": "Workstation"}, {"id": "d", "text": "Mobile"}], "answer": "b", "why": "Built into one device for one purpose."}, {"type": "callout", "variant": "tip", "text": "Serving many clients with no screen attached: server OS. One device, one job: embedded."}]'::jsonb where id = 'a6a73d5c-0941-4459-b50d-1270a9ce7606';

-- OS Components
update lessons set content_blocks = '[{"text": "OS Components", "type": "title", "overview": "The internal building blocks of an operating system: how it organizes files, virtualizes hardware, and manages running software.", "examContext": "Expect a mix of file-system-naming questions (which OS uses which file system) and definition questions on OS internals."}, {"type": "compare", "heading": "File systems", "columns": ["Used by", "Notes"], "rows": [{"label": "NTFS", "values": ["Windows", "Permissions, encryption, large files"]}, {"label": "FAT32", "values": ["USB drives", "Broad compatibility; 4 GB file limit"]}, {"label": "HFS+ / APFS", "values": ["macOS", "Apple file systems"]}, {"label": "ext4", "values": ["Linux", "Common Linux file system"]}]}, {"type": "term_set", "heading": "File system features", "terms": [{"term": "Compression", "short": "Smaller files."}, {"term": "Encryption", "short": "Unreadable without the key."}, {"term": "Permissions", "short": "Who can read, write or execute."}, {"term": "Journaling", "short": "Logs pending changes to recover cleanly after a crash."}]}, {"type": "term_set", "heading": "Running software", "terms": [{"term": "Process", "short": "A program that''s currently running."}, {"term": "Service", "short": "A background process with no interface, such as the print spooler."}, {"term": "Driver", "short": "Lets the OS talk to hardware."}, {"term": "Console (CLI) / GUI", "short": "Text commands / point and click."}, {"term": "Hypervisor", "short": "Runs several OSes on one physical computer."}]}, {"type": "scenario", "prompt": "A user can''t copy a 6 GB video onto a USB stick, though it has 30 GB free. What''s the likely reason?", "choices": [{"id": "a", "text": "It''s NTFS"}, {"id": "b", "text": "It''s formatted FAT32"}, {"id": "c", "text": "It''s journaling"}, {"id": "d", "text": "It''s encrypted"}], "answer": "b", "why": "FAT32 caps single files at 4 GB."}, {"type": "scenario", "prompt": "Which file system feature helps recover cleanly after a sudden power loss?", "choices": [{"id": "a", "text": "Compression"}, {"id": "b", "text": "Journaling"}, {"id": "c", "text": "Encryption"}, {"id": "d", "text": "Permissions"}], "answer": "b", "why": "Journaling logs changes before committing them."}, {"type": "callout", "variant": "tip", "text": "FAT32''s 4 GB limit is a classic. Journaling is about surviving crashes, not security."}]'::jsonb where id = '91cf6e16-b6e6-4884-96a7-9602aadabe86';

-- The Purpose and Use of Software
update lessons set content_blocks = '[{"text": "The Purpose and Use of Software", "type": "title", "overview": "The major categories of application software people use for everyday work tasks.", "examContext": "Expect straightforward matching questions: given an example application or task, name its software category."}, {"type": "compare", "heading": "Software categories", "columns": ["Purpose", "Examples"], "rows": [{"label": "Productivity", "values": ["Create documents, analyze data, build slides", "Word processor, spreadsheet, presentation"]}, {"label": "Collaboration", "values": ["Work together, live or not", "Shared document editors, video calls, messaging"]}, {"label": "Business", "values": ["Support a specific business function", "Accounting, CRM, inventory"]}], "intro": "One app can be in more than one category: a cloud spreadsheet with live co-editing is productivity and collaboration."}, {"type": "scenario", "prompt": "A sales team tracks every customer interaction and deal in one system. Which category?", "choices": [{"id": "a", "text": "Productivity"}, {"id": "b", "text": "Collaboration"}, {"id": "c", "text": "Business (CRM)"}, {"id": "d", "text": "Utility"}], "answer": "c", "why": "CRM supports a specific business function."}, {"type": "scenario", "prompt": "A team meets over video and edits a shared document at the same time. Which category best fits?", "choices": [{"id": "a", "text": "Business"}, {"id": "b", "text": "Collaboration"}, {"id": "c", "text": "Accounting"}, {"id": "d", "text": "Embedded"}], "answer": "b", "why": "Real-time teamwork."}, {"type": "callout", "variant": "tip", "text": "Make things: productivity. Work together: collaboration. Run a business function: business software."}]'::jsonb where id = '22f3e524-0774-4009-b710-92e8a87cd641';

-- Application Architecture and Delivery Models
update lessons set content_blocks = '[{"text": "Application Architecture and Delivery Models", "type": "title", "overview": "Where an application''s code actually runs, and how its logic is split across tiers.", "examContext": "Expect questions distinguishing delivery models (locally installed vs. cloud-hosted) and questions naming the tiers of an n-tier application."}, {"type": "compare", "heading": "Delivery models", "columns": ["Where it runs"], "rows": [{"label": "Locally installed", "values": ["On the user''s own device"]}, {"label": "Local network hosted", "values": ["On a server in the office network"]}, {"label": "Cloud hosted", "values": ["On a provider''s servers, usually through a browser"]}]}, {"type": "diagram", "heading": "A three-tier application", "diagram": {"kind": "flow", "steps": [{"label": "Presentation tier", "note": "What the user sees."}, {"label": "Logic tier", "note": "The application server''s rules."}, {"label": "Data tier", "note": "The database server."}]}}, {"type": "compare", "heading": "Tier counts", "columns": ["Layout"], "rows": [{"label": "One tier", "values": ["Interface, logic and data in one application"]}, {"label": "Two tier", "values": ["A client talks directly to a database server"]}, {"label": "Three tier", "values": ["Presentation, logic and data separated"]}, {"label": "N tier", "values": ["More than three layers"]}]}, {"type": "scenario", "prompt": "A desktop app connects straight to a database server with no application server between. How many tiers?", "choices": [{"id": "a", "text": "One"}, {"id": "b", "text": "Two"}, {"id": "c", "text": "Three"}, {"id": "d", "text": "N"}], "answer": "b", "why": "Client plus database."}, {"type": "scenario", "prompt": "Employees use a timesheet app in their browser that runs on the vendor''s servers. Which delivery model?", "choices": [{"id": "a", "text": "Locally installed"}, {"id": "b", "text": "Local network hosted"}, {"id": "c", "text": "Cloud hosted"}, {"id": "d", "text": "One tier"}], "answer": "c", "why": "Provider servers over the internet."}, {"type": "callout", "variant": "tip", "text": "Three tier: presentation, logic, data. Know it cold."}]'::jsonb where id = '41d28d54-760d-4c3c-80b5-f032fa9c9490';

-- Configuring and Using Web Browsers
update lessons set content_blocks = '[{"text": "Configuring and Using Web Browsers", "type": "title", "overview": "The common configuration options and features found in modern web browsers.", "examContext": "Expect definition-matching questions on each browser feature or setting."}, {"type": "compare", "heading": "Browser features", "columns": ["Does"], "rows": [{"label": "Cache", "values": ["Stores page resources so revisits load faster"]}, {"label": "Scripting", "values": ["Runs JavaScript for interactive pages"]}, {"label": "Add-on / extension", "values": ["Adds features such as a password manager"]}, {"label": "Private browsing", "values": ["Doesn''t keep history, cookies or cache after the session"]}, {"label": "Proxy", "values": ["Forwards requests for filtering, caching or privacy"]}, {"label": "Certificates", "values": ["Confirm a site''s identity for HTTPS"]}, {"label": "Pop-up and script blockers", "values": ["Stop unwanted content running"]}]}, {"type": "key_term", "term": "Private browsing limits", "definition": "It only stops the local device from saving history. The network, employer, ISP and websites can still see activity.", "example": "Using incognito at work still leaves the company''s web filter logging every site visited."}, {"type": "scenario", "prompt": "A website loads much faster the second time because images were saved locally. Which feature?", "choices": [{"id": "a", "text": "Proxy"}, {"id": "b", "text": "Cache"}, {"id": "c", "text": "Scripting"}, {"id": "d", "text": "Certificate"}], "answer": "b", "why": "The cache."}, {"type": "scenario", "prompt": "Does private browsing hide activity from the employer''s network?", "choices": [{"id": "a", "text": "Yes, completely"}, {"id": "b", "text": "No, it only stops local history and cookies"}, {"id": "c", "text": "Only on HTTPS sites"}, {"id": "d", "text": "Only with an extension"}], "answer": "b", "why": "It''s local only."}, {"type": "callout", "variant": "tip", "text": "Private browsing is local only. Cache makes repeat visits faster."}]'::jsonb where id = '9b8ae655-fd49-42c6-aa93-419fc339c0a0';

-- General Application Concepts
update lessons set content_blocks = '[{"text": "General Application Concepts", "type": "title", "overview": "How applications differ in platform support and licensing, and the best practices for installing software safely.", "examContext": "Expect definition questions on licensing types and a scenario question on safe installation practices."}, {"type": "compare", "heading": "Single-platform vs. cross-platform", "columns": ["Single-platform", "Cross-platform"], "rows": [{"label": "Runs on", "values": ["One OS", "Several OSes"]}, {"label": "Example", "values": ["A Windows-only accounting app", "A browser on Windows, macOS and Linux"]}]}, {"type": "compare", "heading": "Licensing types", "columns": ["Cost", "Source code"], "rows": [{"label": "Proprietary / commercial", "values": ["Usually paid", "Closed"]}, {"label": "Open source", "values": ["Often free, not necessarily", "Public"]}, {"label": "Freeware", "values": ["Free", "Closed"]}], "intro": "Separately, a **single-user** license covers one person or device; a **site or volume** license covers many."}, {"type": "term_set", "heading": "Installing safely", "terms": [{"term": "Official sources", "short": "The publisher or a trusted store."}, {"term": "Check requirements", "short": "Before installing."}, {"term": "Read the installer", "short": "Watch permissions and bundled extras."}]}, {"type": "scenario", "prompt": "A free tool lets anyone read and modify its code. What kind of license?", "choices": [{"id": "a", "text": "Freeware"}, {"id": "b", "text": "Open source"}, {"id": "c", "text": "Proprietary"}, {"id": "d", "text": "Site license"}], "answer": "b", "why": "Open source is about code availability.", "trap": "Freeware is also free, but its code is closed."}, {"type": "scenario", "prompt": "A school installs the same software on 500 computers under one agreement. Which license?", "choices": [{"id": "a", "text": "Single-user"}, {"id": "b", "text": "Site or volume"}, {"id": "c", "text": "Freeware"}, {"id": "d", "text": "Open source"}], "answer": "b", "why": "One agreement, many installs."}, {"type": "callout", "variant": "tip", "text": "Freeware is free but closed. Open source means the code is public."}]'::jsonb where id = '525daf65-4b11-402d-8b33-902f749884b1';

-- Domain 3 Recap
update lessons set content_blocks = '[{"text": "Domain 3 Recap", "type": "title", "overview": "The highest-yield facts from all six Applications and Software lessons, condensed for a quick pre-checkpoint review.", "examContext": "Read this closely before attempting the Domain 3 checkpoint."}, {"type": "term_set", "heading": "Operating systems", "terms": [{"term": "Mobile / workstation / server / embedded", "short": "Touch / one user / many clients / one purpose."}, {"term": "NTFS, FAT32, APFS, ext4", "short": "Windows, 4 GB limit, macOS, Linux."}, {"term": "Journaling", "short": "Clean recovery after crashes."}, {"term": "Process / service / driver", "short": "Running program / background / hardware link."}]}, {"type": "term_set", "heading": "Software and browsers", "terms": [{"term": "Productivity, collaboration, business", "short": "Create, team up, run functions."}, {"term": "Three tier", "short": "Presentation, logic, data."}, {"term": "Cache / private browsing", "short": "Faster revisits / local only."}, {"term": "Freeware / open source", "short": "Free but closed / code public."}]}, {"type": "scenario", "prompt": "Which file system has a 4 GB file size limit?", "choices": [{"id": "a", "text": "NTFS"}, {"id": "b", "text": "FAT32"}, {"id": "c", "text": "ext4"}, {"id": "d", "text": "APFS"}], "answer": "b", "why": "FAT32."}, {"type": "scenario", "prompt": "Which tier holds the database in a three-tier app?", "choices": [{"id": "a", "text": "Presentation"}, {"id": "b", "text": "Logic"}, {"id": "c", "text": "Data"}, {"id": "d", "text": "Client"}], "answer": "c", "why": "The data tier."}, {"type": "scenario", "prompt": "A background process with no interface is called what?", "choices": [{"id": "a", "text": "Driver"}, {"id": "b", "text": "Service"}, {"id": "c", "text": "GUI"}, {"id": "d", "text": "Console"}], "answer": "b", "why": "A service."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '5916bbf9-892c-49f6-8281-eb88d4f775cc';

-- Programming Language Categories
update lessons set content_blocks = '[{"text": "Programming Language Categories", "type": "title", "overview": "The major categories of programming and markup languages, and what sets each apart.", "examContext": "Expect questions asking you to classify a named language (Python, HTML, SQL, C++) into its correct category."}, {"type": "compare", "heading": "Language categories", "columns": ["How it works", "Example"], "rows": [{"label": "Interpreted / scripting", "values": ["Run line by line at runtime", "Python, JavaScript"]}, {"label": "Compiled", "values": ["Translated to machine code first", "C, C++"]}, {"label": "Markup", "values": ["Describes structure; no logic", "HTML"]}, {"label": "Query", "values": ["Retrieves and changes database data", "SQL"]}, {"label": "Assembly", "values": ["Near machine level, with readable mnemonics", "x86 assembly"]}]}, {"type": "key_term", "term": "Markup isn''t programming", "definition": "HTML has no logic or calculations, only structure and presentation.", "example": "An HTML file can mark text as a heading, but it can''t add two numbers."}, {"type": "scenario", "prompt": "Which language is used to pull records out of a database?", "choices": [{"id": "a", "text": "HTML"}, {"id": "b", "text": "SQL"}, {"id": "c", "text": "C++"}, {"id": "d", "text": "Assembly"}], "answer": "b", "why": "SQL is a query language."}, {"type": "scenario", "prompt": "A program is turned into a standalone executable before it runs. What kind of language?", "choices": [{"id": "a", "text": "Interpreted"}, {"id": "b", "text": "Compiled"}, {"id": "c", "text": "Markup"}, {"id": "d", "text": "Query"}], "answer": "b", "why": "Compiled ahead of time."}, {"type": "callout", "variant": "tip", "text": "HTML is markup, SQL is query, C++ is compiled, Python is interpreted."}]'::jsonb where id = '65617e8d-648d-4f07-b97a-6a3eacd3dfd9';

-- Pseudocode, Flowcharts, and Program Structure
update lessons set content_blocks = '[{"text": "Pseudocode, Flowcharts, and Program Structure", "type": "title", "overview": "How developers plan program logic before writing real code, and the three fundamental ways code can flow.", "examContext": "Expect questions identifying whether a described scenario is sequence, branching, or looping, and questions defining pseudocode/flowcharts."}, {"type": "compare", "heading": "Planning tools", "columns": ["Pseudocode", "Flowchart"], "rows": [{"label": "Form", "values": ["Plain-language steps", "A diagram"]}, {"label": "Syntax", "values": ["No specific language", "Standard shapes: diamond for decisions, rectangle for actions"]}]}, {"type": "compare", "heading": "The three control structures", "columns": ["What happens", "Cue words"], "rows": [{"label": "Sequence", "values": ["Steps run one after another", "\"Then\""]}, {"label": "Branching", "values": ["Choose a path based on a condition", "\"If this, then that\""]}, {"label": "Looping", "values": ["Repeat a block", "\"Repeat until,\" \"for each\""]}]}, {"type": "key_term", "term": "Looping example", "definition": "Repeating an action for each item or until a condition is met.", "example": "For each student in the class, print their report card."}, {"type": "scenario", "prompt": "\"If the cart total is over $50, apply free shipping; otherwise charge $5.\" Which structure?", "choices": [{"id": "a", "text": "Sequence"}, {"id": "b", "text": "Branching"}, {"id": "c", "text": "Looping"}, {"id": "d", "text": "Assembly"}], "answer": "b", "why": "A decision between paths."}, {"type": "scenario", "prompt": "\"Keep asking for a password until the user enters the right one.\" Which structure?", "choices": [{"id": "a", "text": "Sequence"}, {"id": "b", "text": "Branching"}, {"id": "c", "text": "Looping"}, {"id": "d", "text": "Markup"}], "answer": "c", "why": "Repeat until a condition is met."}, {"type": "callout", "variant": "tip", "text": "If: branching. Repeat or for each: looping. Just steps in order: sequence."}]'::jsonb where id = '65f8fc25-e5b4-418b-aef1-81c6777aaa27';

-- Logic Components, Variables, and Data Containers
update lessons set content_blocks = '[{"text": "Logic Components, Variables, and Data Containers", "type": "title", "overview": "How programs store and organize values in memory while running: variables, constants, arrays, and vectors.", "examContext": "Expect definition and scenario questions distinguishing a variable from a constant, and identifying arrays/vectors."}, {"type": "compare", "heading": "Variable vs. constant", "columns": ["Variable", "Constant"], "rows": [{"label": "Value can change?", "values": ["Yes", "No, set once"]}, {"label": "Example", "values": ["A running total, a player''s score", "Pi, a fixed tax rate"]}]}, {"type": "compare", "heading": "Array vs. vector", "columns": ["Array", "Vector"], "rows": [{"label": "Holds", "values": ["Many values of one type under one name", "The same"]}, {"label": "Size", "values": ["Usually fixed when created", "Grows and shrinks"]}, {"label": "Access", "values": ["By index, usually starting at 0", "By index"]}]}, {"type": "key_term", "term": "Index", "definition": "The position number of an item in an array, usually starting at 0.", "example": "In names = [\"Ana\", \"Ben\", \"Cho\"], names[0] is \"Ana\" and names[2] is \"Cho\"."}, {"type": "scenario", "prompt": "A program stores the speed of light, which never changes. What should it use?", "choices": [{"id": "a", "text": "Variable"}, {"id": "b", "text": "Constant"}, {"id": "c", "text": "Vector"}, {"id": "d", "text": "Loop"}], "answer": "b", "why": "A value fixed for the whole program."}, {"type": "scenario", "prompt": "A shopping list in an app needs to grow as items are added. Which container?", "choices": [{"id": "a", "text": "Fixed array"}, {"id": "b", "text": "Vector"}, {"id": "c", "text": "Constant"}, {"id": "d", "text": "Boolean"}], "answer": "b", "why": "Vectors resize dynamically."}, {"type": "callout", "variant": "tip", "text": "Constants never change. Arrays are usually fixed size; vectors grow and shrink."}]'::jsonb where id = '7d48ed47-4dd5-4960-af3c-5b41d03ea273';

-- Programming Concepts: Objects and Their Properties
update lessons set content_blocks = '[{"text": "Programming Concepts: Objects and Their Properties", "type": "title", "overview": "A first look at object-oriented thinking: how a real-world ''thing'' gets modeled in code as an object with attributes and behaviors.", "examContext": "Expect a scenario question asking you to identify a described value as a property/attribute vs. a method."}, {"type": "key_term", "term": "Object", "definition": "Bundles data (properties) and behavior (methods) to model a real thing.", "example": "A Customer object has name, email and loyaltyPoints, and can placeOrder() or updateEmail()."}, {"type": "compare", "heading": "Property vs. method", "columns": ["Property (attribute)", "Method"], "rows": [{"label": "Is", "values": ["Data describing the object", "An action the object performs"]}, {"label": "Car example", "values": ["color, make, currentSpeed", "accelerate(), brake(), honkHorn()"]}], "cue": ["A noun or characteristic", "A verb, often with parentheses"]}, {"type": "scenario", "prompt": "In a BankAccount object, what is \"balance\"?", "choices": [{"id": "a", "text": "A method"}, {"id": "b", "text": "A property"}, {"id": "c", "text": "A loop"}, {"id": "d", "text": "A constant"}], "answer": "b", "why": "It describes the account''s state."}, {"type": "scenario", "prompt": "In the same object, what is withdraw()?", "choices": [{"id": "a", "text": "A property"}, {"id": "b", "text": "A method"}, {"id": "c", "text": "An array"}, {"id": "d", "text": "A string"}], "answer": "b", "why": "It''s an action the account performs."}, {"type": "callout", "variant": "tip", "text": "Characteristics are properties; actions are methods."}]'::jsonb where id = '19b5b480-fb95-41a3-9e4d-9df67c4b83dc';

-- Domain 4 Recap
update lessons set content_blocks = '[{"text": "Domain 4 Recap", "type": "title", "overview": "The highest-yield facts from all four Software Development Concepts lessons, condensed for a quick pre-checkpoint review.", "examContext": "Read this closely before attempting the Domain 4 checkpoint."}, {"type": "term_set", "heading": "Languages and structure", "terms": [{"term": "Interpreted / compiled", "short": "Python / C++."}, {"term": "Markup / query", "short": "HTML / SQL."}, {"term": "Pseudocode / flowchart", "short": "Plain words / diagram."}, {"term": "Sequence, branching, looping", "short": "In order, if, repeat."}]}, {"type": "term_set", "heading": "Data and objects", "terms": [{"term": "Variable / constant", "short": "Changes / fixed."}, {"term": "Array / vector", "short": "Fixed size / resizable."}, {"term": "Property / method", "short": "Data / action."}]}, {"type": "scenario", "prompt": "HTML is which kind of language?", "choices": [{"id": "a", "text": "Compiled"}, {"id": "b", "text": "Markup"}, {"id": "c", "text": "Query"}, {"id": "d", "text": "Assembly"}], "answer": "b", "why": "Structure only."}, {"type": "scenario", "prompt": "\"For each file in the folder, scan it\" is which structure?", "choices": [{"id": "a", "text": "Sequence"}, {"id": "b", "text": "Branching"}, {"id": "c", "text": "Looping"}, {"id": "d", "text": "Object"}], "answer": "c", "why": "Repeat for each."}, {"type": "scenario", "prompt": "In a Car object, color is what?", "choices": [{"id": "a", "text": "Method"}, {"id": "b", "text": "Property"}, {"id": "c", "text": "Constant"}, {"id": "d", "text": "Array"}], "answer": "b", "why": "A characteristic."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '3cc2f3a9-40fc-4f55-8039-6d88b55d254e';

-- Database Concepts and Purpose
update lessons set content_blocks = '[{"text": "Database Concepts and Purpose", "type": "title", "overview": "What a database is for, how it differs from a simple flat file, and the major categories of data it can hold.", "examContext": "Expect definition questions on structured vs. semi-structured vs. unstructured data, and flat file vs. database."}, {"type": "compare", "heading": "Flat file vs. database", "columns": ["Flat file", "Database"], "rows": [{"label": "Example", "values": ["A single spreadsheet or CSV", "A managed collection of related tables"]}, {"label": "At scale", "values": ["Slow and error-prone", "Handles growth efficiently"]}, {"label": "Many users at once", "values": ["Risky", "Built for it"]}]}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Record", "short": "One complete entry, such as one customer''s details."}, {"term": "Persistence", "short": "Data survives after the program ends."}]}, {"type": "compare", "heading": "Categories of data", "columns": ["Description", "Example"], "rows": [{"label": "Structured", "values": ["Fits rows and columns", "A customer list"]}, {"label": "Semi-structured", "values": ["Some organizing tags, not rigid tables", "JSON or XML"]}, {"label": "Unstructured", "values": ["No predefined format", "Photos, videos, email bodies"]}]}, {"type": "scenario", "prompt": "A folder of security camera videos is what kind of data?", "choices": [{"id": "a", "text": "Structured"}, {"id": "b", "text": "Semi-structured"}, {"id": "c", "text": "Unstructured"}, {"id": "d", "text": "Relational"}], "answer": "c", "why": "No predefined format."}, {"type": "scenario", "prompt": "A JSON file with nested key-value pairs is what kind of data?", "choices": [{"id": "a", "text": "Structured"}, {"id": "b", "text": "Semi-structured"}, {"id": "c", "text": "Unstructured"}, {"id": "d", "text": "Flat"}], "answer": "b", "why": "Some organization, but not rigid tables."}, {"type": "callout", "variant": "tip", "text": "Rows and columns: structured. JSON or XML: semi-structured. Media and free text: unstructured."}]'::jsonb where id = '3af1d327-5bb1-411f-906e-d0db6b93408d';

-- Relational Database Structures
update lessons set content_blocks = '[{"text": "Relational Database Structures", "type": "title", "overview": "The building blocks of a relational database: how tables relate to each other through keys, and how constraints enforce data integrity.", "examContext": "Expect definition questions on primary vs. foreign keys, and questions on what a schema or constraint does."}, {"type": "term_set", "heading": "Key terms at a glance", "terms": [{"term": "Schema", "short": "The blueprint: tables, fields and relationships."}, {"term": "Table", "short": "Rows and columns for one kind of thing."}, {"term": "Row / field", "short": "One record / one piece of data about it."}, {"term": "Constraint", "short": "A rule such as unique, not empty or within a range."}]}, {"type": "compare", "heading": "Primary key vs. foreign key", "columns": ["Primary key", "Foreign key"], "rows": [{"label": "Purpose", "values": ["Uniquely identifies each row", "Points to another table''s primary key"]}, {"label": "Example", "values": ["CustomerID in Customers", "CustomerID in Orders"]}]}, {"type": "diagram", "heading": "A relationship", "diagram": {"kind": "flow", "steps": [{"label": "Customers table", "note": "CustomerID is the primary key."}, {"label": "Orders table", "note": "CustomerID is a foreign key pointing back."}]}}, {"type": "scenario", "prompt": "An Orders table has a CustomerID column that matches the Customers table''s ID. What is that column in Orders?", "choices": [{"id": "a", "text": "Primary key"}, {"id": "b", "text": "Foreign key"}, {"id": "c", "text": "Constraint"}, {"id": "d", "text": "Schema"}], "answer": "b", "why": "It references another table''s primary key."}, {"type": "scenario", "prompt": "A rule prevents two employees from having the same email address. What is it?", "choices": [{"id": "a", "text": "Foreign key"}, {"id": "b", "text": "Constraint"}, {"id": "c", "text": "Schema"}, {"id": "d", "text": "Record"}], "answer": "b", "why": "A uniqueness constraint."}, {"type": "callout", "variant": "tip", "text": "Primary key identifies a row; foreign key links to another table''s primary key."}]'::jsonb where id = 'b5808f8a-98b3-475e-8db2-12680d44cbc5';

-- Non-Relational Databases
update lessons set content_blocks = '[{"text": "Non-Relational Databases", "type": "title", "overview": "An alternative to the strict table structure of relational databases: how key/value and document databases organize data differently.", "examContext": "Expect definition questions distinguishing key/value from document-based non-relational databases."}, {"type": "compare", "heading": "Relational vs. non-relational", "columns": ["Relational", "Non-relational (NoSQL)"], "rows": [{"label": "Structure", "values": ["Fixed columns for every row", "Flexible"]}, {"label": "Fits", "values": ["Consistent, structured data", "Varied, fast-changing or huge data"]}]}, {"type": "compare", "heading": "Two NoSQL types", "columns": ["Key/value", "Document"], "rows": [{"label": "Stores", "values": ["A key and its value", "Self-contained JSON-like documents"]}, {"label": "Structure", "values": ["Simplest possible", "Each document can differ"]}, {"label": "Example", "values": ["Session ID to user", "Product listings with different attributes"]}]}, {"type": "scenario", "prompt": "An app stores session IDs mapped to logged-in users for very fast lookup. Which database type?", "choices": [{"id": "a", "text": "Relational"}, {"id": "b", "text": "Key/value"}, {"id": "c", "text": "Document"}, {"id": "d", "text": "Flat file"}], "answer": "b", "why": "Simple key-to-value lookups."}, {"type": "scenario", "prompt": "A store''s products all have different attributes: shirts have sizes, laptops have RAM. Which fits best?", "choices": [{"id": "a", "text": "Key/value"}, {"id": "b", "text": "Document"}, {"id": "c", "text": "Flat file"}, {"id": "d", "text": "Spreadsheet"}], "answer": "b", "why": "Documents can each have their own fields."}, {"type": "callout", "variant": "tip", "text": "Key/value is a lookup table. Document databases let each record look different."}]'::jsonb where id = '4569d444-292a-4e07-9696-c2a45915f549';

-- Interfacing with Databases
update lessons set content_blocks = '[{"text": "Interfacing with Databases", "type": "title", "overview": "How users and applications actually interact with a database: the statements used to work with data and structure, and the ways that access happens.", "examContext": "Expect direct definition questions distinguishing DML from DDL, and questions on export/import/backup."}, {"type": "compare", "heading": "DML vs. DDL", "columns": ["DML", "DDL"], "rows": [{"label": "Works on", "values": ["The data", "The structure"]}, {"label": "Statements", "values": ["SELECT, INSERT, UPDATE, DELETE", "CREATE, ALTER, DROP, permissions"]}], "cue": ["\"Change the rows\"", "\"Change the table\""]}, {"type": "compare", "heading": "Ways to access a database", "columns": ["How"], "rows": [{"label": "Direct", "values": ["Typing queries in a command-line tool"]}, {"label": "Programmatic", "values": ["Application code sends queries"]}, {"label": "UI based", "values": ["A front-end form builds queries behind the scenes"]}]}, {"type": "term_set", "heading": "Moving and protecting data", "terms": [{"term": "Export", "short": "Data out to a portable file."}, {"term": "Import", "short": "Data in from an outside source."}, {"term": "Backup", "short": "A copy to restore after loss."}]}, {"type": "scenario", "prompt": "A developer adds a new column to an existing table. Which category of statement?", "choices": [{"id": "a", "text": "DML"}, {"id": "b", "text": "DDL"}, {"id": "c", "text": "Query"}, {"id": "d", "text": "Export"}], "answer": "b", "why": "ALTER changes structure."}, {"type": "scenario", "prompt": "UPDATE changes a customer''s phone number. Which category?", "choices": [{"id": "a", "text": "DDL"}, {"id": "b", "text": "DML"}, {"id": "c", "text": "Schema"}, {"id": "d", "text": "Constraint"}], "answer": "b", "why": "It changes data."}, {"type": "callout", "variant": "tip", "text": "DML changes data; DDL changes structure."}]'::jsonb where id = '750da6db-477d-4178-b607-427fa6da4d40';

-- Domain 5 Recap
update lessons set content_blocks = '[{"text": "Domain 5 Recap", "type": "title", "overview": "The highest-yield facts from all four Database Fundamentals lessons, condensed for a quick pre-checkpoint review.", "examContext": "Read this closely before attempting the Domain 5 checkpoint."}, {"type": "term_set", "heading": "Basics and structure", "terms": [{"term": "Database vs. flat file", "short": "Scales and handles many users."}, {"term": "Structured / semi / unstructured", "short": "Tables / JSON / media."}, {"term": "Primary / foreign key", "short": "Identifies / links."}, {"term": "Constraint", "short": "Integrity rule."}]}, {"type": "term_set", "heading": "NoSQL and access", "terms": [{"term": "Key/value / document", "short": "Lookup / flexible records."}, {"term": "DML / DDL", "short": "SELECT, INSERT, UPDATE, DELETE / CREATE, ALTER, DROP."}, {"term": "Direct / programmatic / UI", "short": "Typed / code / forms."}, {"term": "Export, import, backup", "short": "Out, in, protect."}]}, {"type": "scenario", "prompt": "Which statement removes a whole table?", "choices": [{"id": "a", "text": "DELETE"}, {"id": "b", "text": "DROP"}, {"id": "c", "text": "UPDATE"}, {"id": "d", "text": "SELECT"}], "answer": "b", "why": "DROP is DDL."}, {"type": "scenario", "prompt": "Which key uniquely identifies each row?", "choices": [{"id": "a", "text": "Foreign"}, {"id": "b", "text": "Primary"}, {"id": "c", "text": "Constraint"}, {"id": "d", "text": "Index"}], "answer": "b", "why": "Primary key."}, {"type": "scenario", "prompt": "Photos and video are what kind of data?", "choices": [{"id": "a", "text": "Structured"}, {"id": "b", "text": "Semi-structured"}, {"id": "c", "text": "Unstructured"}, {"id": "d", "text": "Relational"}], "answer": "c", "why": "No predefined format."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '17a5674f-f7df-44d4-9e8a-eb595ac62fda';

-- Confidentiality, Integrity, and Availability Concerns
update lessons set content_blocks = '[{"text": "Confidentiality, Integrity, and Availability Concerns", "type": "title", "overview": "The three foundational goals of information security, and the kinds of attacks or events that threaten each one.", "examContext": "Expect scenario questions asking you to identify which CIA principle a described attack or event threatens."}, {"type": "diagram", "heading": "The CIA triad", "diagram": {"kind": "triad", "points": [{"label": "Confidentiality", "note": "Keep data private."}, {"label": "Integrity", "note": "Keep data accurate and unaltered."}, {"label": "Availability", "note": "Keep systems reachable."}], "center": "CIA"}}, {"type": "compare", "heading": "Threats to each", "columns": ["Threats"], "rows": [{"label": "Confidentiality", "values": ["Snooping, wiretapping, social engineering, dumpster diving"]}, {"label": "Integrity", "values": ["Man-in-the-middle, replay attacks, impersonation"]}, {"label": "Availability", "values": ["Denial of service, power outage, hardware failure"]}]}, {"type": "key_term", "term": "Replay attack", "definition": "Capturing valid data such as a login request and sending it again later.", "example": "An attacker records a \"transfer $100\" request and resends it ten times."}, {"type": "scenario", "prompt": "A website is flooded with traffic and real customers can''t reach it. Which goal is threatened?", "choices": [{"id": "a", "text": "Confidentiality"}, {"id": "b", "text": "Integrity"}, {"id": "c", "text": "Availability"}, {"id": "d", "text": "Accounting"}], "answer": "c", "why": "It''s offline for legitimate users."}, {"type": "scenario", "prompt": "An attacker intercepts and alters an invoice''s bank details in transit. Which goal is threatened?", "choices": [{"id": "a", "text": "Confidentiality"}, {"id": "b", "text": "Integrity"}, {"id": "c", "text": "Availability"}, {"id": "d", "text": "Non-repudiation"}], "answer": "b", "why": "The data was changed."}, {"type": "callout", "variant": "tip", "text": "Stolen: confidentiality. Changed: integrity. Offline: availability."}]'::jsonb where id = '27dc0556-3ac3-4a4a-9eec-ea5094cdf8b5';

-- Securing Devices and Best Practices
update lessons set content_blocks = '[{"text": "Securing Devices and Best Practices", "type": "title", "overview": "The fundamental, everyday practices that protect an individual device from common threats.", "examContext": "Expect straightforward scenario questions matching a described protective measure to its name."}, {"type": "term_set", "heading": "Device security basics", "terms": [{"term": "Antivirus / anti-malware", "short": "Finds and removes malicious software."}, {"term": "Host firewall", "short": "Filters traffic for this one device."}, {"term": "Change default passwords", "short": "Factory passwords are widely known."}, {"term": "Patching", "short": "Updates that fix known vulnerabilities."}]}, {"type": "key_term", "term": "Patching", "definition": "Unpatched software with a known flaw is one of the most common causes of breaches.", "example": "Attackers exploit a browser flaw that was fixed three months ago on a PC whose updates were turned off."}, {"type": "scenario", "prompt": "A breach happened through a vulnerability the vendor had already fixed months earlier. What was missing?", "choices": [{"id": "a", "text": "A host firewall"}, {"id": "b", "text": "Patching"}, {"id": "c", "text": "A new password"}, {"id": "d", "text": "Encryption"}], "answer": "b", "why": "The fix existed but wasn''t applied."}, {"type": "scenario", "prompt": "A new smart camera still uses its factory password. What should be done?", "choices": [{"id": "a", "text": "Nothing"}, {"id": "b", "text": "Change the default password"}, {"id": "c", "text": "Install antivirus"}, {"id": "d", "text": "Disable Wi-Fi"}], "answer": "b", "why": "Defaults are public."}, {"type": "callout", "variant": "tip", "text": "Patch, change defaults, run antivirus, use a host firewall."}]'::jsonb where id = '58c70f8e-cd14-4c0e-b4f8-3236b5902525';

-- Behavioral Security Concepts
update lessons set content_blocks = '[{"text": "Behavioral Security Concepts", "type": "title", "overview": "The human and organizational side of security: policies and everyday habits that protect confidential information.", "examContext": "Expect scenario questions on correctly handling confidential information according to policy."}, {"type": "paragraph", "text": "Technology alone can''t secure an organization. **Behavioral security** is the policies and everyday habits that guide how people handle information."}, {"type": "term_set", "heading": "Good habits", "terms": [{"term": "Privacy expectations", "short": "Know what should stay private and respect it."}, {"term": "Written policies", "short": "Acceptable use and data handling rules."}, {"term": "Lock your screen", "short": "Every time you step away."}, {"term": "Watch where you talk", "short": "No sensitive discussions in public."}, {"term": "Shred, don''t toss", "short": "Dispose of sensitive paper securely."}]}, {"type": "scenario", "prompt": "An employee prints a client contract by mistake. How should they dispose of it?", "choices": [{"id": "a", "text": "Regular trash"}, {"id": "b", "text": "Shred it"}, {"id": "c", "text": "Recycling bin"}, {"id": "d", "text": "Leave it on the printer"}], "answer": "b", "why": "Shredding protects sensitive documents."}, {"type": "scenario", "prompt": "A coworker steps away for coffee. What should they do with their computer?", "choices": [{"id": "a", "text": "Leave it open"}, {"id": "b", "text": "Lock the screen"}, {"id": "c", "text": "Turn off the monitor only"}, {"id": "d", "text": "Log out of email only"}], "answer": "b", "why": "Locking stops casual access."}, {"type": "callout", "variant": "tip", "text": "Lock screens, shred sensitive paper, and follow written policy."}]'::jsonb where id = 'd17ffa14-75ec-4522-8a90-9861f60adc70';

-- Authentication, Authorization, Accounting, and Non-Repudiation
update lessons set content_blocks = '[{"text": "Authentication, Authorization, Accounting, and Non-Repudiation", "type": "title", "overview": "The AAA framework that governs identity, access, and accountability, plus the related concept of non-repudiation.", "examContext": "Expect direct definition questions distinguishing authentication from authorization, and identifying MFA factors."}, {"type": "diagram", "heading": "AAA", "diagram": {"kind": "flow", "steps": [{"label": "Authentication", "note": "Who are you?"}, {"label": "Authorization", "note": "What can you do?"}, {"label": "Accounting", "note": "What did you do?"}]}}, {"type": "term_set", "heading": "Related concepts", "terms": [{"term": "Single factor / MFA", "short": "One factor / several independent ones."}, {"term": "SSO", "short": "Log in once, reach many systems."}, {"term": "Least privilege", "short": "Only the access needed."}, {"term": "RBAC", "short": "Permissions assigned by role."}, {"term": "Logs", "short": "Records used for accounting and investigations."}]}, {"type": "key_term", "term": "Non-repudiation", "definition": "Proof that someone can''t later deny an action, such as a digital signature, video, biometric scan or signed receipt.", "example": "A digitally signed contract shows the CFO approved it; she can''t later claim she never did."}, {"type": "scenario", "prompt": "A system records that a user opened the HR folder at 3:14 p.m. Which part of AAA is this?", "choices": [{"id": "a", "text": "Authentication"}, {"id": "b", "text": "Authorization"}, {"id": "c", "text": "Accounting"}, {"id": "d", "text": "Non-repudiation"}], "answer": "c", "why": "Tracking what was done."}, {"type": "scenario", "prompt": "New hires in the support role automatically get support permissions. Which model?", "choices": [{"id": "a", "text": "Least privilege only"}, {"id": "b", "text": "RBAC"}, {"id": "c", "text": "SSO"}, {"id": "d", "text": "MFA"}], "answer": "b", "why": "Permissions follow the role."}, {"type": "callout", "variant": "tip", "text": "Who are you, what can you do, what did you do. A digital signature gives non-repudiation."}]'::jsonb where id = '9b85d226-4265-4567-8a80-01f5c190ba9f';

-- Password Best Practices
update lessons set content_blocks = '[{"text": "Password Best Practices", "type": "title", "overview": "The characteristics of a strong password, and habits that keep credentials secure.", "examContext": "Expect a scenario question asking you to identify the best or worst password practice among several options."}, {"type": "term_set", "heading": "Strong password habits", "terms": [{"term": "Length and complexity", "short": "Long, with mixed case, numbers and symbols."}, {"term": "Unique per account", "short": "One breach doesn''t unlock everything."}, {"term": "No personal information", "short": "No birthdays, names or common words."}, {"term": "Change after a breach", "short": "Promptly, when compromise is known or suspected."}, {"term": "Password manager", "short": "Creates and stores strong, unique passwords."}]}, {"type": "key_term", "term": "Password reuse", "definition": "The classic bad practice: a breach at one site exposes every account sharing the password.", "example": "A forum leak exposes a user''s password, and attackers use it to log into her email and bank."}, {"type": "scenario", "prompt": "Which is the worst password practice?", "choices": [{"id": "a", "text": "Using a password manager"}, {"id": "b", "text": "Using the same password on every site"}, {"id": "c", "text": "Using a long passphrase"}, {"id": "d", "text": "Changing a password after a breach"}], "answer": "b", "why": "Reuse lets one breach cascade."}, {"type": "scenario", "prompt": "Which password is strongest?", "choices": [{"id": "a", "text": "Fluffy2019"}, {"id": "b", "text": "P@ssw0rd"}, {"id": "c", "text": "correct-Maple-Rocket-47!"}, {"id": "d", "text": "johnsmith"}], "answer": "c", "why": "Long and complex without personal information."}, {"type": "callout", "variant": "tip", "text": "Long, unique, no personal details. A password manager makes it practical."}]'::jsonb where id = 'f3ae18ae-5696-425f-87fa-1555f2f8ed33';

-- Common Uses of Encryption
update lessons set content_blocks = '[{"text": "Common Uses of Encryption", "type": "title", "overview": "The basic vocabulary of encryption and the two major situations where it protects data.", "examContext": "Expect a question distinguishing data at rest from data in transit, and a definition question on plain text vs. cipher text."}, {"type": "compare", "heading": "Plain text vs. cipher text", "columns": ["Plain text", "Cipher text"], "rows": [{"label": "Readable?", "values": ["Yes", "No, scrambled"]}, {"label": "Recovered by", "values": ["Not needed", "The right decryption key"]}]}, {"type": "compare", "heading": "Data at rest vs. in transit", "columns": ["At rest", "In transit"], "rows": [{"label": "Where", "values": ["Stored on a drive or database", "Moving across a network"]}, {"label": "Protection", "values": ["Drive or database encryption", "HTTPS and other encrypted connections"]}, {"label": "Threat", "values": ["Stolen device or storage", "Interception"]}]}, {"type": "scenario", "prompt": "A laptop with an encrypted drive is stolen. Which kind of data protection applies?", "choices": [{"id": "a", "text": "Data in transit"}, {"id": "b", "text": "Data at rest"}, {"id": "c", "text": "Plain text"}, {"id": "d", "text": "Hashing"}], "answer": "b", "why": "Stored data."}, {"type": "scenario", "prompt": "Someone snoops on a café''s Wi-Fi but sees only scrambled HTTPS traffic. What protected it?", "choices": [{"id": "a", "text": "Encryption in transit"}, {"id": "b", "text": "Encryption at rest"}, {"id": "c", "text": "A host firewall"}, {"id": "d", "text": "Antivirus"}], "answer": "a", "why": "Data moving over the network."}, {"type": "callout", "variant": "tip", "text": "Stored: at rest. Moving: in transit. Scrambled data is cipher text."}]'::jsonb where id = '701460a1-6388-4b44-b480-2872db4d4310';

-- Business Continuity Concepts
update lessons set content_blocks = '[{"text": "Business Continuity Concepts", "type": "title", "overview": "How organizations prepare to keep operating, or recover quickly, when something goes wrong.", "examContext": "Expect definition questions on redundancy/fault tolerance, and scenario questions about backup and disaster recovery choices."}, {"type": "compare", "heading": "Redundancy vs. fault tolerance vs. backup", "columns": ["What it is", "Example"], "rows": [{"label": "Redundancy", "values": ["Duplicate critical parts", "Two power supplies in a server"]}, {"label": "Fault tolerance", "values": ["Keeps running when a part fails", "The server stays up when one supply dies"]}, {"label": "Backup", "values": ["A copy of data to restore later", "Nightly copy to cloud storage"]}], "intro": "Redundancy is how you achieve fault tolerance. Backups protect data, not uptime."}, {"type": "key_term", "term": "Disaster recovery", "definition": "The broader plan to restore IT systems and operations after a major event, including how fast and in what order.", "example": "After a flood, the plan brings email back first, then accounting, then everything else, from off-site backups."}, {"type": "term_set", "heading": "Backup choices", "terms": [{"term": "Frequency", "short": "How often to copy."}, {"term": "Location", "short": "On site or off site."}, {"term": "Restore speed", "short": "How quickly data must be back."}]}, {"type": "scenario", "prompt": "A server has two power supplies so a single failure doesn''t cause an outage. What technique?", "choices": [{"id": "a", "text": "Backup"}, {"id": "b", "text": "Redundancy"}, {"id": "c", "text": "Encryption"}, {"id": "d", "text": "Disaster recovery"}], "answer": "b", "why": "Duplicate parts."}, {"type": "scenario", "prompt": "A fire destroys the office. Which plan covers restoring all IT operations?", "choices": [{"id": "a", "text": "Backup schedule"}, {"id": "b", "text": "Disaster recovery"}, {"id": "c", "text": "Fault tolerance"}, {"id": "d", "text": "Patching"}], "answer": "b", "why": "The broad restore plan."}, {"type": "callout", "variant": "tip", "text": "Redundancy delivers fault tolerance. Backups protect data. Disaster recovery restores everything."}]'::jsonb where id = 'eb746029-2bfe-4314-9abf-e39972f660d8';

-- Domain 6 Recap
update lessons set content_blocks = '[{"text": "Domain 6 Recap", "type": "title", "overview": "The highest-yield facts from all seven Security lessons, condensed for a quick pre-checkpoint review.", "examContext": "Read this closely before attempting the Domain 6 checkpoint, Security is tied for one of the two largest domains on the exam."}, {"type": "term_set", "heading": "CIA and devices", "terms": [{"term": "Confidentiality", "short": "Snooping, wiretapping, social engineering, dumpster diving."}, {"term": "Integrity", "short": "Man-in-the-middle, replay, impersonation."}, {"term": "Availability", "short": "DoS, power outage, hardware failure."}, {"term": "Device basics", "short": "Antivirus, host firewall, change defaults, patch."}, {"term": "Behavior", "short": "Lock screens, shred, follow policy."}]}, {"type": "term_set", "heading": "Access, passwords, encryption, continuity", "terms": [{"term": "AAA", "short": "Who are you, what can you do, what did you do."}, {"term": "Non-repudiation", "short": "Can''t deny it: signatures, biometrics."}, {"term": "Passwords", "short": "Long, unique, no personal info; never reuse."}, {"term": "At rest / in transit", "short": "Stored / moving."}, {"term": "Redundancy / backup / DR", "short": "Stay up / restore data / restore everything."}]}, {"type": "scenario", "prompt": "Logging in with a password proves what?", "choices": [{"id": "a", "text": "Authorization"}, {"id": "b", "text": "Authentication"}, {"id": "c", "text": "Accounting"}, {"id": "d", "text": "Availability"}], "answer": "b", "why": "Who you are."}, {"type": "scenario", "prompt": "A DoS attack threatens which goal?", "choices": [{"id": "a", "text": "Confidentiality"}, {"id": "b", "text": "Integrity"}, {"id": "c", "text": "Availability"}, {"id": "d", "text": "Non-repudiation"}], "answer": "c", "why": "Availability."}, {"type": "scenario", "prompt": "Which is the classic bad password habit?", "choices": [{"id": "a", "text": "Long passphrases"}, {"id": "b", "text": "Reusing passwords"}, {"id": "c", "text": "Password managers"}, {"id": "d", "text": "MFA"}], "answer": "b", "why": "Reuse."}, {"type": "callout", "variant": "info", "text": "When you''re ready, head to the Domain Checkpoint: fresh scenarios from every lesson in this domain."}]'::jsonb where id = '3d6f9ebe-9cb9-4020-8e5e-a37a8d419579';
